            new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Hölderlin", Text = "Wie unvermögend ist doch der gutwilligste Fleiss der Menschen gegen die Allmacht der ungetheilten Begeisterung.", Author = "Friedrich Hölderlin" },
